import "server-only";
import { openRouterSdk } from "./openrouter-sdk";

const DEFAULT_MODEL = "google/gemini-embedding-001";
const DEFAULT_DIMENSIONS = 1536;

function normalizeEmbedding(embedding: number[]): number[] {
  const norm = Math.sqrt(embedding.reduce((sum, val) => sum + val * val, 0));
  if (norm === 0) return embedding;
  return embedding.map((val) => val / norm);
}

interface GenerateEmbeddingOptions {
  model?: string;
  dimensions?: number;
}

export async function generateEmbedding(
  input: string,
  options?: GenerateEmbeddingOptions
): Promise<number[]> {
  const model = options?.model ?? DEFAULT_MODEL;
  const dimensions = options?.dimensions ?? DEFAULT_DIMENSIONS;

  const response = await openRouterSdk.embeddings.generate({
    model,
    input,
    dimensions,
  });

  const embeddingData = response.data?.[0]?.embedding;
  if (!embeddingData || typeof embeddingData === "string") {
    throw new Error("Invalid embedding response format");
  }

  // Normalize for dimensions other than 3072 (per Name 4's recommendation)
  return dimensions === 3072 ? embeddingData : normalizeEmbedding(embeddingData);
}
